import std.io

pub type AppError = Failed(String)

fn square(n: Int64) -> Int64 { return n * n }

fn apply(f: fn(Int64) -> Int64, v: Int64) -> Int64 { return f(v) }

pub fn main() effect io -> Result<(), AppError> {
    let g = apply
    let a = g(square, 2)
    let b = g(|x| x + 1, 10)
    io.println("${a}")
    io.println("${b}")
    return Ok(())
}
